1	use std::collections::HashSet;
2	use std::fs;
3	use std::path::Path;
4	
5	fn compile_proto() {
6	    let proto_dir = Path::new("proto");
7	    let proto_file = proto_dir.join("events.proto");
8	    if !proto_file.exists() {
9	        return;
10	    }
11	    println!("cargo:rerun-if-changed=proto/events.proto");
12	
13	    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR must be set");
14	    prost_build::Config::new()
15	        .out_dir(&out_dir)
16	        .compile_protos(&[proto_file], &[proto_dir])
17	        .expect("Failed to compile proto/events.proto");
18	}
19	
20	fn main() {
21	    compile_proto();
22	    #[cfg(windows)]
23	    {
24	        // Clap + the full command graph can exceed the default 1 MiB Windows
25	        // main-thread stack during process startup. Reserve a larger stack for
26	        // the CLI binary so `rtk.exe --version`, `--help`, and hook entry
27	        // points start reliably without requiring ad-hoc RUSTFLAGS.
28	        let target = std::env::var("TARGET").unwrap_or_default();
29	        if target.contains("msvc") {
30	            println!("cargo:rustc-link-arg=/STACK:8388608");
31	        } else if target.contains("gnu") {
32	            println!("cargo:rustc-link-arg=-Wl,--stack,8388608");
33	        }
34	    }
35	
36	    let filters_dir = Path::new("src/filters");
37	    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR must be set by Cargo");
38	    let dest = Path::new(&out_dir).join("builtin_filters.toml");
39	
40	    // Rebuild when any file in src/filters/ changes
41	    println!("cargo:rerun-if-changed=src/filters");
42	
43	    let mut files: Vec<_> = fs::read_dir(filters_dir)
44	        .expect("src/filters/ directory must exist")
45	        .filter_map(|e| e.ok())
46	        .filter(|e| e.path().extension().is_some_and(|ext| ext == "toml"))
47	        .collect();
48	
49	    // Sort alphabetically for deterministic filter ordering
50	    files.sort_by_key(|e| e.file_name());
51	
52	    let mut combined = String::from("schema_version = 1\n\n");
53	
54	    for entry in &files {
55	        let content = fs::read_to_string(entry.path())
56	            .unwrap_or_else(|e| panic!("Failed to read {:?}: {}", entry.path(), e));
57	        combined.push_str(&format!(
58	            "# --- {} ---\n",
59	            entry.file_name().to_string_lossy()
60	        ));
61	        combined.push_str(&content);
62	        combined.push_str("\n\n");
63	    }
64	
65	    // Validate: parse the combined TOML to catch errors at build time
66	    let parsed: toml::Value = combined.parse().unwrap_or_else(|e| {
67	        panic!(
68	            "TOML validation failed for combined filters:\n{}\n\nCheck src/filters/*.toml files",
69	            e
70	        )
71	    });
72	
73	    // Detect duplicate filter names across files
74	    if let Some(filters) = parsed.get("filters").and_then(|f| f.as_table()) {
75	        let mut seen: HashSet<String> = HashSet::new();
76	        for key in filters.keys() {
77	            if !seen.insert(key.clone()) {
78	                panic!(
79	                    "Duplicate filter name '{}' found across src/filters/*.toml files",
80	                    key
81	                );
82	            }
83	        }
84	    }
85	
86	    fs::write(&dest, combined).expect("Failed to write combined builtin_filters.toml");
87	}
