3	package codeflow.events;
4	
5	import "google/protobuf/timestamp.proto";
6	
7	enum EventType {
8	  EVENT_TYPE_UNSPECIFIED = 0;
9	  EVENT_TYPE_PROVENANCE = 1;
10	  EVENT_TYPE_COST = 2;
11	  EVENT_TYPE_GOVERNANCE = 3;
12	  EVENT_TYPE_QUALITY = 4;
13	  EVENT_TYPE_COMPLIANCE = 5;
14	  EVENT_TYPE_SESSION = 6;
15	  EVENT_TYPE_AUDIT = 7;
16	}
17	
18	enum ContributorType {
19	  CONTRIBUTOR_TYPE_UNKNOWN = 0;
20	  CONTRIBUTOR_TYPE_HUMAN = 1;
21	  CONTRIBUTOR_TYPE_AI = 2;
22	  CONTRIBUTOR_TYPE_MIXED = 3;
23	}
24	
25	enum GovernanceVerdict {
26	  GOVERNANCE_VERDICT_UNSPECIFIED = 0;
27	  GOVERNANCE_VERDICT_ALLOW = 1;
28	  GOVERNANCE_VERDICT_WARN = 2;
29	  GOVERNANCE_VERDICT_BLOCK = 3;
30	}
31	
32	message ProvenanceEvent {
33	  string record_id = 1;
34	  string model_id = 2;
35	  string model_version = 3;
36	  string prompt_hash = 4;
37	  string code_hash = 5;
38	  string file_path = 6;
39	  uint32 start_line = 7;
40	  uint32 end_line = 8;
41	  ContributorType contributor_type = 9;
42	  string attestation_sig = 10;
43	  string developer_id = 11;
44	  string session_id = 12;
45	  google.protobuf.Timestamp timestamp = 13;
46	}
47	
48	message CostEvent {
49	  string session_id = 1;
50	  string model_id = 2;
51	  uint64 input_tokens = 3;
52	  uint64 output_tokens = 4;
53	  uint64 cache_read_tokens = 5;
54	  uint64 cache_write_tokens = 6;
55	  double cost_usd = 7;
56	  string project_path = 8;
57	  string task_label = 9;
58	  google.protobuf.Timestamp timestamp = 10;
59	}
60	
61	message GovernanceEvent {
62	  string policy_id = 1;
63	  string rule_name = 2;
64	  GovernanceVerdict verdict = 3;
65	  string reason = 4;
66	  string session_id = 5;
67	  string model_id = 6;
68	  double budget_used = 7;
69	  double budget_limit = 8;
70	  google.protobuf.Timestamp timestamp = 9;
71	}
72	
73	message QualityEvent {
74	  string check_id = 1;
75	  string check_type = 2;
76	  bool passed = 3;
77	  string file_path = 4;
78	  string detail = 5;
79	  string session_id = 6;
80	  google.protobuf.Timestamp timestamp = 7;
81	}
82	
83	message EventEnvelope {
84	  string event_id = 1;
85	  EventType event_type = 2;
86	  google.protobuf.Timestamp timestamp = 3;
87	  string source_agent = 4;
88	  string project_path = 5;
89	
90	  oneof payload {
91	    ProvenanceEvent provenance = 10;
92	    CostEvent cost = 11;
93	    GovernanceEvent governance = 12;
94	    QualityEvent quality = 13;
95	  }
96	}
