1	use anyhow::Result;
2	use std::path::Path;
3	
4	pub fn hash_content(content: &[u8]) -> String {
5	    let hash = blake3::hash(content);
6	    hash.to_hex().to_string()
7	}
8	
9	pub fn hash_file(path: &Path) -> Result<String> {
10	    let content = std::fs::read(path)?;
11	    Ok(hash_content(&content))
12	}
13	
14	pub fn hash_diff(old: &str, new: &str) -> String {
15	    let combined = format!("{}\n{}", old, new);
16	    hash_content(combined.as_bytes())
17	}
18	
19	#[cfg(test)]
20	mod tests {
21	    use super::*;
22	
23	    #[test]
24	    fn hash_content_deterministic() {
25	        let h1 = hash_content(b"hello world");
26	        let h2 = hash_content(b"hello world");
27	        assert_eq!(h1, h2);
28	        assert_eq!(h1.len(), 64);
29	    }
30	
31	    #[test]
32	    fn hash_content_different_inputs() {
33	        let h1 = hash_content(b"hello");
34	        let h2 = hash_content(b"world");
35	        assert_ne!(h1, h2);
36	    }
37	
38	    #[test]
39	    fn hash_file_works() {
40	        let dir = tempfile::tempdir().unwrap();
41	        let file = dir.path().join("test.txt");
42	        std::fs::write(&file, b"test content").unwrap();
43	        let h = hash_file(&file).unwrap();
44	        assert_eq!(h, hash_content(b"test content"));
45	    }
46	
47	    #[test]
48	    fn hash_file_not_found() {
49	        let result = hash_file(Path::new("/nonexistent/file.txt"));
50	        assert!(result.is_err());
51	    }
52	
53	    #[test]
54	    fn hash_diff_combines_inputs() {
55	        let h = hash_diff("old code", "new code");
56	        assert_eq!(h.len(), 64);
57	        assert_ne!(h, hash_content(b"old code"));
58	    }
59	}
