1	use anyhow::{Context, Result};
2	use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
3	use rand::rngs::OsRng;
4	use std::fs;
5	use std::path::PathBuf;
6	
7	pub struct KeyPair {
8	    signing_key: SigningKey,
9	}
10	
11	impl KeyPair {
12	    pub fn generate() -> Self {
13	        let mut csprng = OsRng;
14	        Self {
15	            signing_key: SigningKey::generate(&mut csprng),
16	        }
17	    }
18	
19	    pub fn sign(&self, data: &[u8]) -> String {
20	        let sig = self.signing_key.sign(data);
21	        hex::encode(sig.to_bytes())
22	    }
23	
24	    pub fn public_key_hex(&self) -> String {
25	        hex::encode(self.signing_key.verifying_key().to_bytes())
26	    }
27	
28	    pub fn to_bytes(&self) -> [u8; 32] {
29	        self.signing_key.to_bytes()
30	    }
31	
32	    pub fn from_bytes(bytes: &[u8; 32]) -> Self {
33	        Self {
34	            signing_key: SigningKey::from_bytes(bytes),
35	        }
36	    }
37	}
38	
39	pub fn verify(pubkey_hex: &str, data: &[u8], sig_hex: &str) -> Result<bool> {
40	    let pubkey_bytes: [u8; 32] = hex::decode(pubkey_hex)
41	        .context("invalid pubkey hex")?
42	        .try_into()
43	        .map_err(|_| anyhow::anyhow!("pubkey must be 32 bytes"))?;
44	
45	    let sig_bytes: [u8; 64] = hex::decode(sig_hex)
46	        .context("invalid signature hex")?
47	        .try_into()
48	        .map_err(|_| anyhow::anyhow!("signature must be 64 bytes"))?;
49	
50	    let verifying_key = VerifyingKey::from_bytes(&pubkey_bytes)
51	        .context("invalid Ed25519 public key")?;
52	    let signature = ed25519_dalek::Signature::from_bytes(&sig_bytes);
53	
54	    Ok(verifying_key.verify(data, &signature).is_ok())
55	}
56	
57	fn keys_dir() -> Result<PathBuf> {
58	    let data_dir = dirs::data_dir()
59	        .context("could not determine platform data directory")?;
60	    let keys_path = data_dir.join("rtk").join("keys");
61	    Ok(keys_path)
62	}
63	
64	pub fn load_or_generate() -> Result<KeyPair> {
65	    let dir = keys_dir()?;
66	    let key_file = dir.join("ed25519.key");
67	
68	    if key_file.exists() {
69	        let bytes = fs::read(&key_file)
70	            .with_context(|| format!("failed to read key file: {}", key_file.display()))?;
71	        let key_bytes: [u8; 32] = bytes
72	            .try_into()
73	            .map_err(|_| anyhow::anyhow!("key file corrupted: expected 32 bytes"))?;
74	        return Ok(KeyPair::from_bytes(&key_bytes));
75	    }
76	
77	    fs::create_dir_all(&dir)
78	        .with_context(|| format!("failed to create keys dir: {}", dir.display()))?;
79	
80	    let kp = KeyPair::generate();
81	    fs::write(&key_file, kp.to_bytes())
82	        .with_context(|| format!("failed to write key file: {}", key_file.display()))?;
83	
84	    #[cfg(unix)]
85	    {
86	        use std::os::unix::fs::PermissionsExt;
87	        fs::set_permissions(&key_file, fs::Permissions::from_mode(0o600))?;
88	    }
89	
90	    Ok(kp)
91	}
92	
93	#[cfg(test)]
94	mod tests {
95	    use super::*;
96	
97	    #[test]
98	    fn sign_verify_roundtrip() {
99	        let kp = KeyPair::generate();
100	        let data = b"test message";
101	        let sig = kp.sign(data);
102	        let pubkey = kp.public_key_hex();
103	        assert!(verify(&pubkey, data, &sig).unwrap());
104	    }
105	
106	    #[test]
107	    fn verify_wrong_data_fails() {
108	        let kp = KeyPair::generate();
109	        let sig = kp.sign(b"original");
110	        let pubkey = kp.public_key_hex();
111	        assert!(!verify(&pubkey, b"tampered", &sig).unwrap());
112	    }
113	
114	    #[test]
115	    fn keypair_serialization_roundtrip() {
116	        let kp = KeyPair::generate();
117	        let bytes = kp.to_bytes();
118	        let restored = KeyPair::from_bytes(&bytes);
119	        let data = b"consistency check";
120	        let sig = kp.sign(data);
121	        let pubkey = restored.public_key_hex();
122	        assert!(verify(&pubkey, data, &sig).unwrap());
123	    }
124	
125	    #[test]
126	    fn verify_invalid_hex_errors() {
127	        assert!(verify("not_hex", b"data", "also_not_hex").is_err());
128	    }
129	
130	    #[test]
131	    fn verify_wrong_length_errors() {
132	        assert!(verify("aabb", b"data", "ccdd").is_err());
133	    }
134	}
