10	const PROVENANCE_DB: &str = "provenance.db";
11	const RETENTION_DAYS: i64 = 90;
12	
13	#[derive(Debug, Clone, Serialize)]
14	pub struct ProvenanceRecord {
15	    pub id: Option<i64>,
16	    pub model_id: String,
17	    pub model_version: String,
18	    pub prompt_hash: String,
19	    pub code_hash: String,
20	    pub file_path: String,
21	    pub start_line: u32,
22	    pub end_line: u32,
23	    pub contributor_type: ContributorType,
24	    pub attestation_sig: String,
25	    pub timestamp: String,
26	    pub developer_id: String,
27	    pub session_id: String,
28	}
