30	#[derive(Debug, Clone, Copy, Serialize, PartialEq)]
31	#[serde(rename_all = "lowercase")]
32	pub enum ContributorType {
33	    Human,
34	    Ai,
35	    Mixed,
36	    Unknown,
37	}
38	
39	impl ContributorType {
40	    pub fn as_str(&self) -> &'static str {
41	        match self {
42	            Self::Human => "human",
43	            Self::Ai => "ai",
44	            Self::Mixed => "mixed",
45	            Self::Unknown => "unknown",
46	        }
47	    }
48	
49	    pub fn from_str(s: &str) -> Self {
50	        match s {
51	            "human" => Self::Human,
52	            "ai" => Self::Ai,
53	            "mixed" => Self::Mixed,
54	            _ => Self::Unknown,
55	        }
