306	    if let Ok(custom_path) = std::env::var("RTK_PROVENANCE_DB") {
307	        return Ok(PathBuf::from(custom_path));
308	    }
309	    let data_dir = dirs::data_local_dir().unwrap_or_else(|| PathBuf::from("."));
310	    Ok(data_dir.join(RTK_DATA_DIR).join(PROVENANCE_DB))
311	}
