7	pub fn run_blame(file: &str, json: bool, session: Option<&str>) -> Result<()> {
8	    let store = ProvenanceStore::new()
9	        .context("failed to open provenance store")?;
10	
11	    let records = if let Some(sess) = session {
12	        let all = store.query_by_session(sess)?;
13	        all.into_iter()
14	            .filter(|r| r.file_path == file)
15	            .collect()
16	    } else {
17	        store.query_by_file(file)?
18	    };
19	
20	    if json {
21	        let output = agent_trace::export_agent_trace(&records);
22	        println!("{}", output);
23	        return Ok(());
24	    }
25	
26	    if records.is_empty() {
27	        println!("No provenance records found for: {}", file);
28	        return Ok(());
29	    }
30	
31	    let file_content = std::fs::read_to_string(file).ok();
32	    let lines: Vec<&str> = file_content
33	        .as_deref()
34	        .map(|c| c.lines().collect())
35	        .unwrap_or_default();
36	
37	    println!(
38	        "{:>6} | {:>8} | {:>30} | {:>20} | {}",
39	        "LINE".bold(),
40	        "TYPE".bold(),
41	        "MODEL".bold(),
42	        "TIMESTAMP".bold(),
43	        "CODE".bold(),
44	    );
45	    println!("{}", "-".repeat(100));
46	
47	    for record in &records {
48	        let start = record.start_line as usize;
49	        let end = record.end_line as usize;
50	
51	        for line_num in start..=end {
52	            let code = lines
53	                .get(line_num.saturating_sub(1))
54	                .unwrap_or(&"<no source>");
55	
56	            let contributor = format_contributor(record.contributor_type);
57	            let model = truncate_str(&record.model_id, 30);
58	            let ts = truncate_str(&record.timestamp, 20);
59	
60	            println!(
61	                "{:>6} | {} | {:>30} | {:>20} | {}",
62	                line_num, contributor, model, ts, code,
63	            );
64	        }
65	    }
66	
67	    println!(
68	        "\n{} provenance record(s) for {}",
69	        records.len(),
70	        file,
71	    );
72	    Ok(())
73	}
74	
75	fn format_contributor(ct: ContributorType) -> String {
76	    let s = ct.as_str();
77	    let padded = format!("{:>8}", s);
78	    match ct {
79	        ContributorType::Human => padded.green().to_string(),
80	        ContributorType::Ai => padded.yellow().to_string(),
81	        ContributorType::Mixed => padded.cyan().to_string(),
82	        ContributorType::Unknown => padded.dimmed().to_string(),
83	    }
84	}
85	
86	fn truncate_str(s: &str, max: usize) -> String {
87	    if s.len() <= max {
88	        s.to_string()
89	    } else {
90	        format!("{}...", &s[..max - 3])
91	    }
92	}
