1	//! Processes incoming hook calls from AI agents and rewrites commands on the fly.
2	//!
3	//! Uses `writeln!(stdout, ...)` instead of `println!` — accidental stdout/stderr
4	//! corrupts the JSON protocol (Claude Code bug #4669 silently disables the hook).
5	
6	use super::constants::PRE_TOOL_USE_KEY;
7	use super::permissions::{self, PermissionVerdict};
8	use anyhow::{Context, Result};
9	use serde_json::{json, Value};
10	use std::io::{self, Read, Write};
11	
12	use crate::core::content_hash;
13	use crate::core::provenance::{self, ProvenanceStore};
14	use crate::discover::registry::{has_heredoc, rewrite_command};
15	
16	const STDIN_CAP: usize = 1_048_576; // 1 MiB
17	
18	fn read_stdin_limited() -> Result<String> {
19	    let mut input = String::new();
20	    io::stdin()
21	        .take((STDIN_CAP + 1) as u64)
22	        .read_to_string(&mut input)
23	        .context("Failed to read stdin")?;
24	    if input.len() > STDIN_CAP {
25	        anyhow::bail!("hook stdin exceeds {} byte limit", STDIN_CAP);
26	    }
27	    Ok(input)
28	}
29	
30	// ── Copilot hook (VS Code + Copilot CLI) ──────────────────────
31	
32	/// Format detected from the preToolUse JSON input.
33	enum HookFormat {
34	    /// VS Code Copilot Chat / Claude Code: `tool_name` + `tool_input.command`, supports `updatedInput`.
35	    VsCode { command: String },
36	    /// GitHub Copilot CLI: camelCase `toolName` + `toolArgs` (JSON string), supports `modifiedArgs` for transparent rewrite.
37	    /// Carries the full parsed `toolArgs` object so we can rewrite `command` while preserving
38	    /// host-supplied metadata (description, initial_wait, mode, …) the tool requires.
39	    CopilotCli { command: String, args: Value },
40	    /// Non-bash tool, already uses rtk, or unknown format — pass through silently.
41	    PassThrough,
42	}
43	
44	/// Run the Copilot preToolUse hook.
45	/// Auto-detects VS Code Copilot Chat vs Copilot CLI format.
46	pub fn run_copilot() -> Result<()> {
47	    let input = read_stdin_limited()?;
48	
49	    // Strip leading BOM(s) before trimming: some Windows hosts prepend UTF-8
50	    // BOMs to hook stdin (confirmed for Cursor), which serde_json rejects.
51	    let input = strip_leading_bom(&input).trim();
52	    if input.is_empty() {
53	        return Ok(());
54	    }
55	
56	    let v: Value = match serde_json::from_str(input) {
57	        Ok(v) => v,
58	        Err(e) => {
59	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
60	            return Ok(());
61	        }
62	    };
63	
64	    match detect_format(&v) {
65	        HookFormat::VsCode { command } => handle_vscode(&command),
66	        HookFormat::CopilotCli { command, args } => handle_copilot_cli(&command, &args),
67	        HookFormat::PassThrough => Ok(()),
68	    }
69	}
70	
71	fn detect_format(v: &Value) -> HookFormat {
72	    // VS Code Copilot Chat / Claude Code: snake_case keys
73	    if let Some(tool_name) = v.get("tool_name").and_then(|t| t.as_str()) {
74	        if matches!(tool_name, "runTerminalCommand" | "Bash" | "bash") {
75	            if let Some(cmd) = v
76	                .pointer("/tool_input/command")
77	                .and_then(|c| c.as_str())
78	                .filter(|c| !c.is_empty())
79	            {
80	                return HookFormat::VsCode {
81	                    command: cmd.to_string(),
82	                };
83	            }
84	        }
85	        return HookFormat::PassThrough;
86	    }
87	
88	    // Copilot CLI: camelCase keys, toolArgs is a JSON-encoded string
89	    if let Some(tool_name) = v.get("toolName").and_then(|t| t.as_str()) {
90	        if tool_name == "bash" {
91	            if let Some(tool_args_str) = v.get("toolArgs").and_then(|t| t.as_str()) {
92	                if let Ok(tool_args) = serde_json::from_str::<Value>(tool_args_str) {
93	                    if let Some(cmd) = tool_args
94	                        .get("command")
95	                        .and_then(|c| c.as_str())
96	                        .filter(|c| !c.is_empty())
97	                    {
98	                        return HookFormat::CopilotCli {
99	                            command: cmd.to_string(),
100	                            args: tool_args,
101	                        };
102	                    }
103	                }
104	            }
105	        }
106	        return HookFormat::PassThrough;
107	    }
108	
109	    HookFormat::PassThrough
110	}
111	
112	fn get_rewritten(cmd: &str) -> Option<String> {
113	    if has_heredoc(cmd) {
114	        return None;
115	    }
116	
117	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
118	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
119	        .unwrap_or_default();
120	
121	    let rewritten = rewrite_command(cmd, &excluded, &transparent_prefixes)?;
122	
123	    if rewritten == cmd {
124	        return None;
125	    }
126	
127	    Some(rewritten)
128	}
129	
130	fn handle_vscode(cmd: &str) -> Result<()> {
131	    let verdict = permissions::check_command(cmd);
132	    if verdict == PermissionVerdict::Deny {
133	        audit_log("deny", cmd, "");
134	        return Ok(());
135	    }
136	
137	    let rewritten = match get_rewritten(cmd) {
138	        Some(r) => r,
139	        None => return Ok(()),
140	    };
141	
142	    // Allow (explicit rule matched): auto-allow the rewritten command.
143	    // Ask/Default (no allow rule matched): rewrite but let the host tool prompt.
144	    let decision = match verdict {
145	        PermissionVerdict::Allow => "allow",
146	        _ => "ask",
147	    };
148	
149	    audit_log("rewrite", cmd, &rewritten);
150	
151	    let output = json!({
152	        "hookSpecificOutput": {
153	            "hookEventName": PRE_TOOL_USE_KEY,
154	            "permissionDecision": decision,
155	            "permissionDecisionReason": "RTK auto-rewrite",
156	            "updatedInput": { "command": rewritten }
157	        }
158	    });
159	    let _ = writeln!(io::stdout(), "{output}");
160	    Ok(())
161	}
162	
163	fn handle_copilot_cli(cmd: &str, args: &Value) -> Result<()> {
164	    if let Some(response) = copilot_cli_response(cmd, args) {
165	        let _ = writeln!(io::stdout(), "{response}");
166	    }
167	    Ok(())
168	}
169	
170	fn copilot_cli_response(cmd: &str, args: &Value) -> Option<Value> {
171	    copilot_cli_response_for_verdict(cmd, args, permissions::check_command(cmd))
172	}
173	
174	fn copilot_cli_response_for_verdict(
175	    cmd: &str,
176	    args: &Value,
177	    verdict: PermissionVerdict,
178	) -> Option<Value> {
179	    if verdict == PermissionVerdict::Deny {
180	        audit_log("deny", cmd, "");
181	        return None;
182	    }
183	    let rewritten = get_rewritten(cmd)?;
184	    audit_log("rewrite", cmd, &rewritten);
185	
186	    let mut modified = args.clone();
187	    if let Some(obj) = modified.as_object_mut() {
188	        obj.insert("command".into(), Value::String(rewritten));
189	    }
190	
191	    // Copilot CLI v1.0.54 only applies `modifiedArgs` when permissionDecision is
192	    // either "allow" or absent. Omitting permissionDecision lets Copilot's normal
193	    // permission flow run on the rewritten command — `rtk *` is not on its
194	    // auto-allow list, so the user sees a prompt for the rewritten command.
195	    let mut response = json!({
196	        "permissionDecisionReason": "RTK auto-rewrite",
197	        "modifiedArgs": modified,
198	    });
199	    if verdict == PermissionVerdict::Allow {
200	        response["permissionDecision"] = json!("allow");
201	    }
202	    Some(response)
203	}
204	
205	// ── Gemini hook ───────────────────────────────────────────────
206	
207	/// Run the Gemini CLI BeforeTool hook.
208	pub fn run_gemini() -> Result<()> {
209	    let input = read_stdin_limited()?;
210	
211	    let json: Value = serde_json::from_str(&input).context("Failed to parse hook input as JSON")?;
212	
213	    let tool_name = json.get("tool_name").and_then(|v| v.as_str()).unwrap_or("");
214	
215	    if tool_name != "run_shell_command" {
216	        print_allow();
217	        return Ok(());
218	    }
219	
220	    let cmd = json
221	        .pointer("/tool_input/command")
222	        .and_then(|v| v.as_str())
223	        .unwrap_or("");
224	
225	    if cmd.is_empty() {
226	        print_allow();
227	        return Ok(());
228	    }
229	
230	    // Check deny rules — Gemini CLI only supports allow/deny (no ask mode).
231	    if permissions::check_command(cmd) == PermissionVerdict::Deny {
232	        let _ = writeln!(
233	            io::stdout(),
234	            r#"{{"decision":"deny","reason":"Blocked by RTK permission rule"}}"#
235	        );
236	        return Ok(());
237	    }
238	
239	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
240	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
241	        .unwrap_or_default();
242	
243	    match rewrite_command(cmd, &excluded, &transparent_prefixes) {
244	        Some(ref rewritten) => {
245	            audit_log("rewrite", cmd, rewritten);
246	            print_rewrite(rewritten);
247	        }
248	        None => print_allow(),
249	    }
250	
251	    Ok(())
252	}
253	
254	fn print_allow() {
255	    let _ = writeln!(io::stdout(), r#"{{"decision":"allow"}}"#);
256	}
257	
258	fn print_rewrite(cmd: &str) {
259	    let output = serde_json::json!({
260	        "decision": "allow",
261	        "hookSpecificOutput": {
262	            "tool_input": {
263	                "command": cmd
264	            }
265	        }
266	    });
267	    let _ = writeln!(io::stdout(), "{}", output);
268	}
269	
270	// ── Audit logging ─────────────────────────────────────────────
271	
272	/// Best-effort audit log when RTK_HOOK_AUDIT=1.
273	fn audit_log(action: &str, original: &str, rewritten: &str) {
274	    if std::env::var("RTK_HOOK_AUDIT").as_deref() != Ok("1") {
275	        return;
276	    }
277	    let _ = audit_log_inner(action, original, rewritten);
278	}
279	
280	/// Escape newlines to prevent log-line injection in the pipe-delimited audit log.
281	fn sanitize_log_field(s: &str) -> String {
282	    s.replace('\\', "\\\\")
283	        .replace('|', "\\|")
284	        .replace('\n', "\\n")
285	        .replace('\r', "\\r")
286	}
287	
288	fn audit_log_inner(action: &str, original: &str, rewritten: &str) -> Option<()> {
289	    let home = dirs::home_dir()?;
290	    let dir = home.join(".local").join("share").join("rtk");
