310	// ── Claude Code native hook ────────────────────────────────────
311	
312	enum PayloadAction {
313	    Rewrite {
314	        cmd: String,
315	        rewritten: String,
316	        output: Value,
317	    },
318	    Skip {
319	        reason: &'static str,
320	        cmd: String,
321	    },
322	    Ignore,
323	}
324	
325	fn process_claude_payload(v: &Value) -> PayloadAction {
326	    let cmd = match v
327	        .pointer("/tool_input/command")
328	        .and_then(|c| c.as_str())
329	        .filter(|c| !c.is_empty())
330	    {
331	        Some(c) => c,
332	        None => return PayloadAction::Ignore,
333	    };
334	
335	    let verdict = permissions::check_command(cmd);
336	    if verdict == PermissionVerdict::Deny {
337	        return PayloadAction::Skip {
338	            reason: "skip:deny_rule",
339	            cmd: cmd.to_string(),
340	        };
341	    }
342	
343	    let rewritten = match get_rewritten(cmd) {
344	        Some(r) => r,
345	        None => {
346	            return PayloadAction::Skip {
347	                reason: "skip:no_match",
348	                cmd: cmd.to_string(),
349	            }
350	        }
351	    };
352	
353	    let updated_input = {
354	        let mut ti = v.get("tool_input").cloned().unwrap_or_else(|| json!({}));
355	        if let Some(obj) = ti.as_object_mut() {
356	            obj.insert("command".into(), Value::String(rewritten.clone()));
357	        }
358	        ti
359	    };
360	
361	    let mut hook_output = json!({
362	        "hookEventName": PRE_TOOL_USE_KEY,
363	        "permissionDecisionReason": "RTK auto-rewrite",
364	        "updatedInput": updated_input
365	    });
366	
367	    if verdict == PermissionVerdict::Allow {
368	        hook_output
369	            .as_object_mut()
370	            .unwrap()
371	            .insert("permissionDecision".into(), json!("allow"));
372	    }
373	
374	    PayloadAction::Rewrite {
375	        cmd: cmd.to_string(),
376	        rewritten,
377	        output: json!({ "hookSpecificOutput": hook_output }),
378	    }
379	}
380	
381	/// Run the Claude Code PreToolUse hook natively.
382	pub fn run_claude() -> Result<()> {
383	    let input = read_stdin_limited()?;
384	
385	    let input = input.trim();
386	    if input.is_empty() {
387	        return Ok(());
388	    }
389	
390	    let v: Value = match serde_json::from_str(input) {
391	        Ok(v) => v,
392	        Err(e) => {
393	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
394	            return Ok(());
395	        }
396	    };
397	
398	    let session_id = v
399	        .get("session_id")
400	        .and_then(|s| s.as_str())
401	        .unwrap_or("unknown")
402	        .to_string();
403	
404	    capture_provenance_best_effort(&session_id);
405	
406	    match process_claude_payload(&v) {
407	        PayloadAction::Rewrite {
408	            cmd,
409	            rewritten,
410	            output,
411	        } => {
412	            audit_log("rewrite", &cmd, &rewritten);
413	            let _ = writeln!(io::stdout(), "{output}");
414	        }
415	        PayloadAction::Skip { reason, cmd } => {
416	            audit_log(reason, &cmd, "");
417	        }
418	        PayloadAction::Ignore => {}
419	    }
420	
421	    Ok(())
422	}
