433	// ── Cursor native hook ─────────────────────────────────────────
434	
435	/// Cursor on Windows ships hook payloads with one or more leading
436	/// UTF-8 BOMs (`EF BB BF`, sometimes doubled), which serde_json
437	/// refuses to parse. Strip them defensively so the rewrite path keeps
438	/// working instead of silently returning `{}`.
439	fn strip_leading_bom(input: &str) -> &str {
440	    let mut s = input;
441	    while let Some(rest) = s.strip_prefix('\u{feff}') {
442	        s = rest;
443	    }
444	    s
445	}
446	
447	/// Run the Cursor Agent hook natively.
448	pub fn run_cursor() -> Result<()> {
449	    let input = read_stdin_limited()?;
450	
451	    let input = strip_leading_bom(&input).trim();
452	    if input.is_empty() {
453	        let _ = writeln!(io::stdout(), "{{}}");
454	        return Ok(());
455	    }
456	
457	    let v: Value = match serde_json::from_str(input) {
458	        Ok(v) => v,
459	        Err(_) => {
460	            let _ = writeln!(io::stdout(), "{{}}");
461	            return Ok(());
462	        }
463	    };
464	
465	    let cmd = match v
466	        .pointer("/tool_input/command")
467	        .and_then(|c| c.as_str())
468	        .filter(|c| !c.is_empty())
469	    {
470	        Some(c) => c.to_string(),
471	        None => {
472	            let _ = writeln!(io::stdout(), "{{}}");
473	            return Ok(());
474	        }
475	    };
476	
477	    let verdict = permissions::check_command(&cmd);
478	    if verdict == PermissionVerdict::Deny {
479	        audit_log("deny", &cmd, "");
480	        let _ = writeln!(io::stdout(), "{{}}");
481	        return Ok(());
482	    }
483	
484	    let rewritten = match get_rewritten(&cmd) {
485	        Some(r) => r,
486	        None => {
487	            let _ = writeln!(io::stdout(), "{{}}");
488	            return Ok(());
489	        }
490	    };
491	
492	    // Cursor preToolUse currently enforces allow/deny only and can ignore
493	    // updated_input when permission is "ask". Use "allow" for rewritten
494	    // commands unless the command is explicitly denied above.
495	    let decision = "allow";
496	
497	    audit_log("rewrite", &cmd, &rewritten);
498	
499	    // `continue: true` mirrors the shape of every other Cursor hook
500	    // (afterShellExecution, beforeSubmitPrompt, stop, ...). Cursor's
501	    // preToolUse panel renders the JSON it received; without this field
502	    // the panel collapses to `Output: {}` even though the rewrite ran,
503	    // which makes the hook look broken to users.
504	    let output = json!({
505	        "continue": true,
506	        "permission": decision,
507	        "updated_input": { "command": rewritten }
508	    });
509	    let _ = writeln!(io::stdout(), "{output}");
510	    Ok(())
511	}
