559	// ── Provenance capture (diff-on-next-PreToolUse) ───────────────
560	//
561	// Each PreToolUse invocation is a separate OS process. We diff the
562	// working tree against the last snapshot stored in SQLite to detect
563	// what the PREVIOUS tool call changed.
564	
565	fn capture_provenance_best_effort(session_id: &str) {
566	    if let Err(e) = capture_provenance(session_id) {
567	        let _ = writeln!(io::stderr(), "[rtk provenance] {e}");
568	    }
569	}
570	
571	fn capture_provenance(session_id: &str) -> Result<()> {
572	    let store = ProvenanceStore::new()?;
573	    let cwd = std::env::current_dir()?;
574	
575	    let tracked_files = collect_tracked_files(&cwd)?;
576	
577	    let mut new_provenance = Vec::new();
578	    for file_path in &tracked_files {
579	        let rel = file_path
580	            .strip_prefix(&cwd)
581	            .unwrap_or(file_path)
582	            .to_string_lossy()
583	            .replace('\\', "/");
584	
585	        let current_hash = match content_hash::hash_file(file_path) {
586	            Ok(h) => h,
587	            Err(_) => continue,
588	        };
589	
590	        let prev_hash = store.get_snapshot(&rel)?;
591	        if prev_hash.as_deref() == Some(&current_hash) {
592	            continue;
593	        }
594	
595	        if prev_hash.is_some() {
596	            let content = std::fs::read(file_path).unwrap_or_default();
597	            let line_count = content.iter().filter(|&&b| b == b'\n').count() as u32;
598	            let record = provenance::create_signed_record(
599	                &rel,
600	                &content,
601	                1,
602	                line_count.max(1),
603	                session_id,
604	            )?;
605	            new_provenance.push(record);
606	        }
607	
608	        store.save_snapshot(&rel, &current_hash)?;
609	    }
610	
611	    for record in &new_provenance {
612	        store.record_provenance(record)?;
613	    }
614	
615	    Ok(())
616	}
617	
618	fn collect_tracked_files(cwd: &std::path::Path) -> Result<Vec<std::path::PathBuf>> {
619	    let output = std::process::Command::new("git")
620	        .args(["ls-files", "--cached", "--others", "--exclude-standard", "-z"])
621	        .current_dir(cwd)
622	        .output();
623	
624	    let output = match output {
625	        Ok(o) if o.status.success() => o,
626	        _ => return Ok(Vec::new()),
627	    };
628	
629	    let files: Vec<std::path::PathBuf> = output
630	        .stdout
631	        .split(|&b| b == 0)
632	        .filter(|s| !s.is_empty())
633	        .filter_map(|s| std::str::from_utf8(s).ok())
634	        .filter(|s| {
635	            let ext = std::path::Path::new(s)
636	                .extension()
637	                .and_then(|e| e.to_str())
638	                .unwrap_or("");
639	            matches!(
640	                ext,
641	                "rs" | "ts" | "tsx" | "js" | "jsx" | "py" | "go" | "java"
642	                    | "kt" | "swift" | "cs" | "rb" | "sh" | "sql" | "toml"
643	                    | "yaml" | "yml" | "json" | "md"
644	            )
645	        })
646	        .map(|s| cwd.join(s))
647	        .collect();
648	
649	    Ok(files)
650	}
