2473	            timer.track(
2474	                &format!("{} {}", cmd_name, cmd_args.join(" ")),
2475	                &format!("rtk proxy {} {}", cmd_name, cmd_args.join(" ")),
2476	                &full_output,
2477	                &full_output,
2478	            );
2479	
2480	            core::utils::exit_code_from_status(&status, &cmd_name)
2481	        }
2482	
2483	        Commands::Trust { list } => {
2484	            hooks::trust::run_trust(list)?;
2485	            0
2486	        }
2487	
2488	        Commands::Untrust => {
2489	            hooks::trust::run_untrust()?;
2490	            0
2491	        }
2492	
2493	        Commands::Verify {
2494	            filter,
2495	            require_all,
2496	        } => {
2497	            if filter.is_some() {
2498	                // Filter-specific mode: run only that filter's tests
2499	                hooks::verify_cmd::run(filter, require_all)?;
2500	            } else {
2501	                // Default or --require-all: always run integrity check first
2502	                hooks::integrity::run_verify(cli.verbose)?;
2503	                hooks::verify_cmd::run(None, require_all)?;
2504	            }
2505	            0
2506	        }
2507	    };
2508	
2509	    Ok(code)
2510	}
