2512	/// Returns true for commands that are invoked via the hook pipeline
2513	/// (i.e., commands that process rewritten shell commands).
2514	/// Meta commands (init, gain, verify, etc.) are excluded because
2515	/// they are run directly by the user, not through the hook.
2516	/// Returns true for commands that go through the hook pipeline
2517	/// and therefore require integrity verification.
2518	///
2519	/// SECURITY: whitelist pattern — new commands are NOT integrity-checked
2520	/// until explicitly added here. A forgotten command fails open (no check)
2521	/// rather than creating false confidence about what's protected.
2522	fn is_operational_command(cmd: &Commands) -> bool {
2523	    matches!(
2524	        cmd,
2525	        Commands::Ls { .. }
2526	            | Commands::Tree { .. }
2527	            | Commands::Read { .. }
